-- Nexmark qhopv on flink, BLACKHOLE sink variant. NOT a nexmark query. qhop's
-- windowed counts with the window start projected and a primary key, so
-- upsert_gate.sh compares the VALUES rather than the row count. This exists
-- because a window that fires early emits the same NUMBER of panes with lower
-- counts in them, so no row-count gate can see an undercount - which is the
-- failure mode a multi-partition watermark produces, and the one 34819d4
-- fixed once already. This is the check that would notice it coming back.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-qhopvbh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_qhopv (`wstart` BIGINT, `auction` BIGINT, `num` BIGINT) WITH ('connector' = 'blackhole');
INSERT INTO sink_qhopv
SELECT CAST(UNIX_TIMESTAMP(CAST(window_start AS STRING)) * 1000 AS BIGINT) AS wstart, auction, COUNT(*) AS num FROM TABLE(HOP(TABLE bid, DESCRIPTOR(ts), INTERVAL '2' SECOND, INTERVAL '10' SECOND)) GROUP BY window_start, window_end, auction;
